'use strict';
const SHELL='clinical-shell-da6b8dde8727f526';
const $=s=>document.querySelector(s),esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={emergency:'急症急救',orders:'临床医嘱',drugs:'本院药品',templates:'病历模板',documents:'医疗文书'};
const state={unlocked:false,module:'home',setting:'',category:'',query:'',scope:'focused',page:0,job:0,epoch:0,manifest:null,ready:{},busy:false,progress:0,progressMessage:'正在读取资料清单',current:null,heads:{},idle:15};
function chineseError(e,fallback){return e&&/[\u4e00-\u9fff]/.test(e.message||'')?e.message:fallback;}
let searchWorker=null,searchTimer,noticeTimer,lastAction=Date.now(),pending=null,printFrame=null;
function toast(s){$('#notice').textContent=s;$('#notice').style.display='block';clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').style.display='none',5000);}
function network(){if(window.PORTABLE){$('#network').textContent='本地便携模式';return;}const online=navigator.onLine;$('#network').textContent=online?'网络已连接':'当前离线';$('#network').classList.toggle('offline',!online);}
function menu(){const nav=[['home','工作台','▦'],['emergency','急症急救','✚'],['orders','临床医嘱','≡'],['drugs','本院药品','◉'],['templates','病历模板','▤'],['documents','医疗文书','▧']];$('#nav').innerHTML=nav.map(([m,n,i])=>'<button class="nav-item '+(state.module===m?'active':'')+'" data-module="'+m+'"'+(state.module===m?' aria-current="page"':'')+'><span aria-hidden="true">'+i+'</span>'+n+(!state.unlocked&& !['home','emergency'].includes(m)?'<span class="lock" aria-label="需解锁">锁</span>':'')+'</button>').join('');$('#lockHint').textContent=state.unlocked?'当前会话已解锁':'其余资料已锁定';$('#lockBtn').textContent=state.unlocked?'锁定资料':'解锁资料';$('#topLock').textContent=state.unlocked?'锁定资料':'解锁资料';$('#searchInput').placeholder=state.unlocked?'搜索名称、常见症状、药品功效或病症':'搜索急救名称、症状或处置内容';$('#searchHint').textContent=state.unlocked?'常用字段快速搜索 · 全文搜索请切换范围后点击搜索 · 命中注明字段':'当前免密码搜索急救资料 · 支持名称、拼音和首字母';}
function requestUnlock(after){pending=after||null;$('#password').value='';$('#passwordError').textContent='';if(!$('#lockDialog').open)$('#lockDialog').showModal();setTimeout(()=>$('#password').focus(),30);}
function lock(){state.unlocked=false;state.epoch++;state.current=null;state.heads={};state.job++;if(searchWorker){searchWorker.terminate();searchWorker=null;}closeReader();$('#copyText').value='';$('#manualCopy').hidden=true;$('#searchInput').value='';state.query='';state.category='';if(printFrame){printFrame.remove();printFrame=null;}navigate('home');toast('资料已锁定，急救仍可直接使用。');}
async function active(module){if(module==='emergency')return await K.meta('active:emergency');return await K.meta('activeDataset');}
async function refreshReady(){for(const m of Object.keys(names)){const v=await active(m);state.ready[m]=v&&await K.meta('ready:'+v+'|'+m)?v:null;}}
function home(){const emergencyReady=!!state.ready.emergency,all=Object.keys(names).every(m=>state.ready[m]);return '<div class="welcome"><div><p class="eyebrow">临床资料查阅</p><h1>临床工作台</h1><p>急救资料直接使用，其余资料解锁后查阅。</p></div><span class="date">'+new Intl.DateTimeFormat('zh-CN',{dateStyle:'long'}).format(new Date())+'</span></div><div class="dashboard"><div><button class="emergency-hero wide" data-module="emergency"><div><span class="red-tag">免密码快速通道</span><h2>急症急救快速通道</h2><p>4 本原始资料 · 116 项操作与处置流程</p></div><span class="hero-arrow" aria-hidden="true">↗</span></button><div class="section-head"><h2>急救资料目录</h2><span>按原始工作簿分类</span></div><div class="book-grid">'+[['基础生命支持操作',10],['急救处理',44],['急救流程图',10],['急症处理',52]].map(([n,c],i)=>'<button class="book" data-book="'+n+'"><span class="book-number">0'+(i+1)+'</span><strong>'+n+'</strong><small>'+c+' 项资料</small><span class="arrow" aria-hidden="true">↗</span></button>').join('')+'</div><div class="section-head"><h2>临床知识资料</h2><span>'+(state.unlocked?'本次会话已解锁':'解锁后查阅')+'</span></div><div class="locked-modules">'+['orders','drugs','templates','documents'].map(m=>'<button data-module="'+m+'">'+names[m]+' <span aria-hidden="true">'+(state.unlocked?'→':'⌑')+'</span></button>').join('')+'</div></div><aside class="side-panels"><div class="panel"><h2>离线资料准备</h2><div class="status-line"><span>急救资料</span><span class="status-text">'+(emergencyReady?'已就绪':'准备中')+'</span></div><div class="status-line"><span>全部知识</span><span class="status-text">'+(all?'已就绪':'尚未全部准备')+'</span></div><progress max="100" value="'+state.progress+'" aria-label="资料准备进度"></progress><p class="progress-msg">'+esc(state.progressMessage)+'</p><button class="outline wide" data-action="prepare">'+(state.busy?'正在核对资料…':window.PORTABLE?'校验本地资料文件':all?'核对离线资料':'准备全部离线资料')+'</button><p class="footnote">'+(window.PORTABLE?'本版不需安装、联网或导入。请保留完整文件夹，双击网页即可使用。':'首次从网站准备需要网络；本机服务读取本地资料不需要外网。准备完成后可离线查阅。')+'</p></div><div class="panel"><h2>原始资料状态</h2><span class="status-badge">已保留来源与分类</span><p>原文不改写。详情中的缺失、重复与待核对状态均保留。</p><button class="text-btn" data-action="settings">查看资料与离线设置 →</button></div></aside></div>';}
function render(){menu();$('#breadcrumb').textContent=state.module==='home'?'工作台':state.module==='settings'?'离线与设置':state.module==='all'?'全部资料搜索':names[state.module];if(state.module==='home'){$('#view').innerHTML=home();return;}if(state.module==='settings'){settings();return;}if(!['emergency','all'].includes(state.module)&&!state.unlocked){$('#view').innerHTML='<div class="empty"><h2>解锁后查阅资料</h2><p>急症急救快速通道始终免密码。</p><button class="primary" data-action="unlock">解锁资料</button></div>';return;}const m=state.module;$('#view').innerHTML='<div class="welcome"><div><p class="eyebrow">'+(m==='emergency'?'免密码快速通道':'临床知识资料')+'</p><h1>'+esc(m==='all'?'全部资料搜索':names[m])+'</h1></div><button class="text-btn" data-module="home">返回工作台</button></div><div class="filters" id="filters"></div><div class="result-meta" id="resultMeta">正在读取资料…</div><div id="results"></div><div class="pagination" id="pages"></div>';loadFilters();runSearch();}
async function navigate(m,opts){if(!['home','emergency','settings','all'].includes(m)&&!Object.prototype.hasOwnProperty.call(names,m))m='home';if(m==='all'&&!state.unlocked)m='emergency';if(!['home','emergency','settings'].includes(m)&&!state.unlocked){requestUnlock(()=>navigate(m,opts));return;}state.epoch++;state.module=m;state.page=0;state.category=opts&&opts.category||'';state.setting=opts&&opts.setting||'';state.query=$('#searchInput').value.trim();if(m==='home'){$('#searchInput').value='';state.query='';}location.hash=m;$('.sidebar').classList.remove('open');$('#menuBtn').setAttribute('aria-expanded','false');render();}
async function loadFilters(){const token=state.epoch,m=state.module;const filter=$('#filters');if(!filter)return;let cats=[];if(m!=='all'&&state.ready[m]){const hs=await K.allHeads(state.ready[m]+'|'+m);if(token!==state.epoch)return;const found=new Set(hs.map(h=>h.category));const sourceOrder=Object.keys(state.manifest&&state.manifest.categories[m]||{});cats=sourceOrder.filter(c=>found.has(c)).concat(Array.from(found).filter(c=>!sourceOrder.includes(c)));}if(!$('#filters'))return;$('#filters').innerHTML=(m==='templates'?'<label>使用场景<select id="settingFilter"><option value="">全部场景</option><option value="out">门诊模板（含通用待核对）</option><option value="in">住院模板（含通用待核对）</option><option value="shared">仅通用／待核对</option><option value="mixed">仅混合待核对</option></select></label>':'')+(m!=='all'?'<label>原始分类<select id="categoryFilter"><option value="">全部分类</option>'+cats.map(c=>'<option value="'+esc(c)+'">'+esc(c)+'</option>').join('')+'</select></label>':'')+'<label>搜索范围<select id="scopeFilter"><option value="focused">常用字段（名称、症状、功效、病症）</option><option value="full">全文（含禁忌、不良反应）</option></select></label>';if($('#categoryFilter'))$('#categoryFilter').value=state.category;if($('#settingFilter'))$('#settingFilter').value=state.setting;$('#scopeFilter').value=state.scope;}
function getWorker(){if(!searchWorker)searchWorker=window.PORTABLE?new PortableSearch():new Worker('search-worker.js');return searchWorker;}
async function runSearch(){if(!$('#results'))return;const job=++state.job,epoch=state.epoch;const modules=(state.module==='all'?(state.unlocked?Object.keys(names):['emergency']):[state.module]).filter(m=>state.ready[m]);if(!modules.length){$('#resultMeta').textContent='当前模块尚未准备';$('#results').innerHTML='<div class="empty"><h2>先准备离线资料</h2><p>导入过程保留全部原文、分类与来源。</p><button class="primary" data-action="prepare">准备资料</button></div>';return;}$('#resultMeta').textContent='正在检索本地资料…';const w=getWorker();w.onerror=()=>{if(job===state.job&&$('#resultMeta'))$('#resultMeta').textContent='搜索组件未能启动，请刷新后重试。';};w.onmessage=e=>{const r=e.data;if(r.job!==state.job||epoch!==state.epoch||!$('#results'))return;if(r.error){$('#resultMeta').textContent=r.error;return;}$('#resultMeta').textContent='共 '+r.total.toLocaleString('zh-CN')+' 条'+(state.query?'匹配结果':'资料')+' · 每页 40 条'+(state.module==='templates'?' · 通用与混合项保留待核对标记':'');$('#results').innerHTML=r.results.length?'<div class="result-list">'+r.results.map(x=>result(x)).join('')+'</div>':'<div class="empty"><h2>没有找到匹配资料</h2><p>请减少关键词或切换分类。缺失字段不会自动补写。</p></div>';$('#pages').innerHTML='<button class="outline" id="prevPage" '+(state.page===0?'disabled':'')+'>上一页</button><span>第 '+(state.page+1)+' / '+Math.max(1,Math.ceil(r.total/40))+' 页</span><button class="outline" id="nextPage" '+((state.page+1)*40>=r.total?'disabled':'')+'>下一页</button>';};w.postMessage({job,modules:modules.map(m=>({module:m,version:state.ready[m]})),query:state.query,category:state.category,setting:state.setting,scope:state.scope,page:state.page});}
function highlight(t){let s=esc(t);const words=state.query.split(/\s+/).filter(Boolean).sort((a,b)=>b.length-a.length);if(!words.length)return s;const reg=new RegExp('('+words.map(w=>esc(w).replace(/[.*+?^$()|[\]\\]/g,'\\$&')).join('|')+')','gi');return s.replace(reg,'<mark>$1</mark>');}
function result(x){const r=x.header;let tag=r.missingDetails?'源表详情缺失':r.setting==='shared'?'通用／待核对':r.setting==='mixed'?'混合待核对':r.flags&&r.flags.length?'待人工核对':r.duplicateIds?'重复来源已保留':'';return '<button class="result" data-record="'+esc(r.key)+'"><div class="result-top"><strong>'+highlight(r.title)+'</strong>'+(tag?'<span class="badge warn">'+tag+'</span>':'<span aria-hidden="true">↗</span>')+'</div><small>'+esc(names[r.module])+' / '+esc(r.category)+(r.caseName?' · '+esc(r.caseName):'')+'</small>'+(x.hit?'<p class="hit"><span class="hit-label">命中'+esc(x.hit.label)+'：</span>'+highlight(x.hit.text)+'</p>':'')+'</button>';}
function closeReader(){if($('#reader').open)$('#reader').close();$('#readerBody').replaceChildren();$('#readerFlags').replaceChildren();state.current=null;}
function field(title,v){if(v===undefined)return '';let body;if(v===null||v===''||Array.isArray(v)&&!v.length)body='<p class="source-note">源资料未提供</p>';else if(Array.isArray(v))body='<ul>'+v.map(x=>'<li>'+esc(K.flat(x)).replace(/\n/g,'<br>')+'</li>').join('')+'</ul>';else body='<pre>'+esc(K.flat(v))+'</pre>';return '<section class="field"><h3>'+esc(title)+'</h3>'+body+'</section>';}
async function openRecord(key){const epoch=state.epoch;let r;try{r=await K.get('records',key);}catch(e){toast(chineseError(e,'资料文件读取失败，请重新解压完整运行包。'));return;}if(epoch!==state.epoch||!r)return;if(r.module!=='emergency'&&!state.unlocked){requestUnlock(()=>openRecord(key));return;}state.current=r;$('#manualCopy').hidden=true;$('#copyText').value='';$('#readerTitle').textContent=r.title;$('#readerCategory').textContent=names[r.module]+' / '+r.category;$('#readerSource').textContent=r.locator.file+' · '+(r.locator.sheet?'工作表：'+r.locator.sheet+(r.locator.excelRow?' / 第'+r.locator.excelRow+'行':''):r.locator.arrayRow?'记录'+r.locator.arrayRow+(r.locator.caseRow?' / 病例'+r.locator.caseRow:''):'文书'+r.locator.documentRow);let flags=[];if(r.flags)flags=flags.concat(r.flags);if(r.missingDetails)flags.push('源表未提供成分至相互作用等详情，不能按缺失的功效或病症检索。');if(r.setting==='shared'||r.setting==='mixed')flags.push(r.setting==='mixed'?'包含门诊和住院结构，场景待核对。':'通用／待核对资料，未强行归入门诊或住院。');if(r.emptyTemplates&&r.emptyTemplates.length)flags.push('源正文为空：'+r.emptyTemplates.join('、'));if(r.escapedNewlines&&r.escapedNewlines.length)flags.push('部分正文包含源文件的转义换行标记，本应用保留原文。');if(r.duplicateIds)flags.push('检测到相同内容的其他来源记录，全部保留。');$('#readerFlags').innerHTML=flags.map(f=>'<p class="flag">'+esc(f)+'</p>').join('');$('#templateSelectLabel').hidden=r.module!=='templates';if(r.module==='templates'){$('#templateSelect').innerHTML='<option value="">同一病例的全部内容</option>'+Object.keys(r.raw.case.templates).map(k=>'<option value="'+esc(k)+'">'+esc(k)+'</option>').join('');}$('#copyBtn').hidden=false;renderRecord();if(!$('#reader').open)$('#reader').showModal();}
function documentSrc(r){return '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src &#39;none&#39;; style-src &#39;unsafe-inline&#39;; script-src &#39;none&#39;; base-uri &#39;none&#39;; form-action &#39;none&#39;"><title>'+esc(r.title)+'</title><style>'+r.raw.css+'</style></head><body>'+r.raw.fragment+'</body></html>';}
function renderRecord(){const r=state.current;if(!r)return;const b=$('#readerBody');if(r.module==='documents'){b.innerHTML='<p class="source-note">文书保留原格式，窄屏可左右滑动查看。</p><div class="document-scroll"><iframe class="document-frame" title="原格式医疗文书" sandbox="allow-same-origin allow-modals"></iframe></div>';const f=b.querySelector('iframe');f.onload=()=>{try{f.style.height=Math.max(900,f.contentDocument.documentElement.scrollHeight+24)+'px';}catch(e){}};f.srcdoc=documentSrc(r);return;}if(r.module==='emergency'){b.innerHTML='<pre class="'+(r.flow?'flow-text':'emergency-text')+'">'+esc(r.raw.lines.join('\n'))+'</pre>';return;}if(r.module==='templates'){const chosen=$('#templateSelect').value;let output='';if(!chosen){['icd10_diagnosis','icd10_secondary','icd9cm3_procedure'].forEach(k=>{if(r.raw.case[k]&&K.flat(r.raw.case[k]))output+=field(K.labels[k],r.raw.case[k]);});}Object.keys(r.raw.case.templates).forEach(k=>{if(!chosen||chosen===k)output+=field(k,r.raw.case.templates[k]);});b.innerHTML=output;return;}b.innerHTML=Object.keys(r.raw).map(k=>field(K.labels[k]||k,r.raw[k])).join('');}
function currentPlain(){const r=state.current;if(!r)return '';if(r.module==='documents')return r.raw.text;if(r.module==='emergency')return r.raw.lines.join('\n');if(r.module==='templates'){const k=$('#templateSelect').value;return Object.keys(r.raw.case.templates).filter(x=>!k||x===k).map(x=>x+'\n'+(r.raw.case.templates[x]||'源正文为空')).join('\n\n');}return Object.keys(r.raw).map(k=>(K.labels[k]||k)+'\n'+(K.flat(r.raw[k])||'源资料未提供')).join('\n\n');}
function checkAccess(){return !!state.current&&(state.current.module==='emergency'||state.unlocked);}
async function copyCurrent(){if(!checkAccess())return;const token=state.epoch,r=state.current,plain=currentPlain();let rich=false;try{if(navigator.clipboard&&window.ClipboardItem&&r.module==='documents'){const blob=new Blob(['<style>'+r.raw.css+'</style>'+r.raw.fragment],{type:'text/html'});await navigator.clipboard.write([new ClipboardItem({'text/html':blob,'text/plain':new Blob([plain],{type:'text/plain'})})]);rich=true;}else if(navigator.clipboard)await navigator.clipboard.writeText(plain);else throw Error();if(token!==state.epoch)return;toast(rich?'已复制原格式内容。':'已复制纯文本内容。');}catch(e){if(token!==state.epoch)return;try{if(!navigator.clipboard)throw Error();await navigator.clipboard.writeText(plain);if(token===state.epoch)toast('格式复制不可用，已复制纯文本。');return;}catch(fallbackError){}if(token!==state.epoch)return;$('#manualCopy').hidden=false;$('#copyText').value=plain;$('#copyText').focus();$('#copyText').select();toast('自动复制不可用，请在文本框中手动复制。');}}
function printCurrent(){if(!checkAccess())return;const r=state.current,epoch=state.epoch;let src;if(r.module==='documents')src=documentSrc(r);else{const css='@page{size:A4;margin:18mm 16mm}body{font:14px/1.8 "Microsoft YaHei","PingFang SC",sans-serif;color:#202b35}h1{font-size:22px}h3{font-size:16px;margin:18px 0 8px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit}li{margin:6px 0}.source-note{font-size:11px;color:#555}.field{break-inside:auto}.field h3{break-after:avoid}.flag{border:1px solid #999;padding:8px}.flow-text{font:12px/1.5 "NSimSun","SimSun",monospace;white-space:pre;overflow:visible}';src='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>'+esc(r.title)+'</title><style>'+css+'</style></head><body><h1>'+esc(r.title)+'</h1><p class="source-note">'+esc($('#readerSource').textContent)+'</p>'+$('#readerFlags').innerHTML+$('#readerBody').innerHTML+'</body></html>';}if(printFrame)printFrame.remove();const f=document.createElement('iframe');f.title='打印预览';f.className='print-frame';f.setAttribute('sandbox','allow-same-origin allow-modals');f.style.cssText='position:fixed;width:1px;height:1px;right:0;bottom:0;border:0;opacity:0;pointer-events:none';document.body.appendChild(f);printFrame=f;f.onload=()=>{if(epoch!==state.epoch||!checkAccess()){f.remove();return;}setTimeout(()=>{if(epoch!==state.epoch||!checkAccess())return;try{f.contentWindow.focus();f.contentWindow.print();}catch(e){toast('浏览器限制了打印，请通过系统打印菜单重试。');}},200);};f.srcdoc=src;}
async function checkedChunk(c){if(state.manifest.transport==='classic-script-v1'){const rows=await ClinicalChunks.load(c.url);if(rows.length!==c.count||await K.hash(new TextEncoder().encode(JSON.stringify(rows)))!==c.sha256)throw Error('资料分块完整性校验失败。');return rows;}let res;try{res=await fetch(c.url,{cache:'no-store'});}catch(e){throw Error('资料下载中断，请连接网络后重试。');}if(!res.ok)throw Error('无法读取资料分块，请连接网络后重试。');const b=await res.arrayBuffer();if(await K.hash(b)!==c.sha256)throw Error('资料完整性校验失败：'+c.url);const rows=JSON.parse(new TextDecoder().decode(b));if(rows.length!==c.count||rows.some(r=>r.version!==state.manifest.version||r.module!==c.module||r.moduleKey!==r.version+'|'+r.module||r.key!==r.version+'|'+r.id))throw Error('资料清单不匹配。');return rows;}
async function importModule(m){const mf=state.manifest,v=mf.version;for(const c of mf.chunks.filter(c=>c.module===m)){const mark='chunk:'+v+':'+c.url;if(!await K.meta(mark)){const rows=await checkedChunk(c);await K.putChunk(rows,mark);}state.progressMessage='正在准备'+names[m]+' · 已提交资料分块';updateProgress();}const count=await K.count(v+'|'+m);if(count!==mf.counts[m])throw Error(names[m]+'数量校验未通过');await K.setMeta('ready:'+v+'|'+m,true);if(m==='emergency')await K.setMeta('active:emergency',v);await refreshReady();}
function updateProgress(){document.querySelectorAll('progress').forEach(x=>x.value=state.progress);document.querySelectorAll('.progress-msg').forEach(x=>x.textContent=state.progressMessage);}
async function ensureShell(){if(!('serviceWorker' in navigator)||!window.isSecureContext)throw Error('完整离线缓存需要安全连接或本机服务。');await Promise.race([navigator.serviceWorker.ready,new Promise((_,reject)=>setTimeout(()=>reject(Error('应用离线缓存尚未就绪，请联网刷新后重试。')),15000))]);const cache=await caches.open(SHELL);for(const p of ['index.html','app.css','app.js','db.js','chunks.js','portable.js','search-core.js','search-worker.js','manifest.webmanifest','icons/icon.svg','icons/icon-192.png','icons/icon-512.png','data/manifest.json'])if(!await cache.match(new URL(p,location.href).href))throw Error('应用框架尚未缓存完整，请刷新后重试。');}
async function prepare(all){if(window.PORTABLE){if(state.busy)return;state.busy=true;state.progress=0;try{await Portable.verifyAll((n,total)=>{state.progress=Math.round(n/total*100);state.progressMessage='正在核对本地资料：'+n+' / '+total;updateProgress();});state.progressMessage='全部7752条资料文件已读取核对，直接按需使用。';toast(state.progressMessage);}catch(e){state.progressMessage=chineseError(e,'本地资料不完整，请重新解压完整包。');toast(state.progressMessage);}finally{state.busy=false;render();}return;}if(state.busy){toast('正在准备资料，请稍候。');return;}state.busy=true;state.progress=0;state.progressMessage='正在校验资料';if(state.module==='home'||state.module==='settings')render();try{if(!state.manifest)throw Error('资料清单不可用，请联网刷新。');await ensureShell();await K.setMeta('manifest:'+state.manifest.version,state.manifest);const mm=all?['emergency','orders','drugs','templates','documents']:['emergency'];for(let i=0;i<mm.length;i++){await importModule(mm[i]);state.progress=Math.round((i+1)/mm.length*100);updateProgress();}if(all){await K.setMeta('activeDataset',state.manifest.version);await refreshReady();}state.progressMessage=all?'全部知识已校验，可离线使用。':'急救资料已就绪，可免密码离线查阅。';if(all)toast(state.progressMessage);}catch(e){state.progressMessage=e.name==='QuotaExceededError'?'本机空间不足，已保留上个完整版本。请释放空间后重试。':chineseError(e,'资料处理失败，请检查网络与本机空间后重试。');toast(state.progressMessage);}finally{state.busy=false;state.epoch++;render();}}
async function settings(){if(window.PORTABLE){portableSettings();return;}const epoch=state.epoch;let usage='浏览器暂未提供容量信息';try{if(navigator.storage&&navigator.storage.estimate){const s=await navigator.storage.estimate();usage='已用约 '+Math.round((s.usage||0)/1048576)+' 兆字节 / 配额约 '+Math.round((s.quota||0)/1048576)+' 兆字节';}}catch(e){}if(epoch!==state.epoch)return;const all=Object.keys(names).every(m=>state.ready[m]);$('#view').innerHTML='<div class="welcome"><div><p class="eyebrow">本机资料管理</p><h1>离线与设置</h1></div></div><div class="settings-layout"><div class="panel"><h2>离线资料状态</h2>'+Object.keys(names).map(m=>'<div class="status-line"><span>'+names[m]+'</span><span class="status-text">'+(state.ready[m]?'已就绪':'尚未准备')+'</span></div>').join('')+'<progress max="100" value="'+state.progress+'" aria-label="资料准备进度"></progress><p class="progress-msg">'+esc(state.progressMessage)+'</p><div class="actions"><button class="primary" data-action="prepare">准备或重新核对全部资料</button><button class="outline" data-action="persist">请求浏览器持久保存</button></div><p>'+usage+'</p><p>浏览器可能清理本地数据。请保留备份；首次准备须联网，准备完成后可断网刷新使用。</p></div><div class="panel"><h2>备份与恢复</h2><p>备份包含已准备的全部原文及来源信息，不加密。导出和恢复需先解锁；恢复不会保留解锁状态。</p><div class="actions"><button class="outline" data-action="backup">导出资料备份</button><button class="outline" data-action="restore">从备份恢复</button></div><input id="restoreFile" type="file" accept=".json,application/json" hidden></div><div class="panel"><h2>自动锁定</h2><label for="idleSelect">闲置多久后锁定受保护资料</label><select id="idleSelect"><option value="0">不自动锁定</option><option value="5">5 分钟</option><option value="15">15 分钟</option><option value="30">30 分钟</option></select><p>刷新后默认锁定。急救始终免密码。此功能仅锁定界面，不能阻止通过源文件或开发者工具读取资料。</p></div><div class="panel"><h2>资料版本与原文状态</h2><p>应用版本：2.0.0<br>来源日期：2026年11月11日<br>原始压缩包未修改；重复记录保留独立来源。</p>'+(state.unlocked?'<p>药品详情缺失151行；病历场景未定277例、混合5例；空病程正文1个。分类为结构候选，待核对状态保留。</p>':'<p>解锁后查看受保护资料的详细状态。</p>')+'<p>旧系统两种浏览器的目标为第109版。实际旧系统、苹果和安卓真机兼容性以交付测试报告为准。</p></div></div>';$('#idleSelect').value=String(state.idle);}
function download(name,blob){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000);}
async function backup(){if(!state.unlocked){requestUnlock(backup);return;}if(state.busy){toast('请等待资料准备完成。');return;}const token=state.epoch;toast('正在整理本机资料备份…');try{const dataset=await K.meta('activeDataset'),ev=await K.meta('active:emergency');const versions=Array.from(new Set([dataset,ev].filter(Boolean)));if(!versions.length)throw Error('尚无已准备的资料');const chunks=[];for(const v of versions){const mf=await K.meta('manifest:'+v);if(!mf)continue;for(const c of mf.chunks){const keys=await K.meta('chunk:'+v+':'+c.url+':ids');if(!keys)continue;const rows=[];for(const k of keys)rows.push(await K.get('records',k));if(!state.unlocked||token!==state.epoch)throw Error('界面状态已改变，请重新解锁后导出。');chunks.push({version:v,url:c.url,rows});}}download('临床资料备份_'+new Date().toISOString().slice(0,10)+'.json',new Blob([JSON.stringify({format:'clinical-desk-backup-1',manifests:await Promise.all(versions.map(v=>K.meta('manifest:'+v))),activeDataset:dataset,emergencyVersion:ev,chunks})],{type:'application/json'}));toast('备份文件已准备下载。');}catch(e){toast('备份失败：'+chineseError(e,'本机资料暂时无法读取，请重试。'));}}
async function restore(file){if(!state.unlocked)return;if(state.busy){toast('请等待当前资料准备结束。');return;}state.busy=true;const epoch=state.epoch;try{toast('正在校验备份文件…');const b=JSON.parse(await file.text());if(b.format!=='clinical-desk-backup-1'||!Array.isArray(b.manifests)||!Array.isArray(b.chunks))throw Error('不是本工作站的备份文件');const known=state.manifest;for(const mf of b.manifests){if(!mf||mf.version!==known.version||JSON.stringify(mf.sources)!==JSON.stringify(known.sources)||JSON.stringify(mf.chunks)!==JSON.stringify(known.chunks))throw Error('备份来源版本与当前程序不一致，请使用匹配版本程序恢复。');}for(const ch of b.chunks){if(!state.unlocked||epoch!==state.epoch)throw Error('已锁定，请重新恢复');const c=known.chunks.find(x=>x.url===ch.url);if(ch.version!==known.version||!c||!Array.isArray(ch.rows)||ch.rows.length!==c.count||await K.hash(new TextEncoder().encode(JSON.stringify(ch.rows)))!==c.sha256)throw Error('备份分块校验失败');}for(const ch of b.chunks){const mark='chunk:'+ch.version+':'+ch.url;await K.putChunk(ch.rows,mark);}await K.setMeta('manifest:'+known.version,known);for(const m of Object.keys(names)){if(await K.count(known.version+'|'+m)===known.counts[m])await K.setMeta('ready:'+known.version+'|'+m,true);}if(b.activeDataset){for(const m of Object.keys(names))if(!await K.meta('ready:'+known.version+'|'+m))throw Error('完整资料备份存在缺失');await K.setMeta('activeDataset',known.version);}if(b.emergencyVersion&&await K.meta('ready:'+known.version+'|emergency'))await K.setMeta('active:emergency',known.version);await refreshReady();lock();toast('备份恢复完成，资料已重新锁定。');}catch(e){toast('恢复失败：'+chineseError(e,'备份文件损坏或格式不正确。')+'；上个完整版本保持不变。');}finally{state.busy=false;}}
document.addEventListener('click',e=>{lastAction=Date.now();const el=e.target.closest('button,a');if(!el)return;if(el.dataset.module){navigate(el.dataset.module);return;}if(el.dataset.book){navigate('emergency',{category:el.dataset.book});return;}if(el.dataset.record){openRecord(el.dataset.record);return;}const action=el.dataset.action;if(action==='prepare')prepare(true);if(action==='settings')navigate('settings');if(action==='unlock')requestUnlock();if(action==='persist'){if(navigator.storage&&navigator.storage.persist)navigator.storage.persist().then(ok=>toast(ok?'浏览器已允许持久保存。':'浏览器未批准持久保存，请保留备份。'));else toast('当前浏览器不支持此请求，请保留备份。');}if(action==='backup')backup();if(action==='restore'){if(!state.unlocked)requestUnlock(()=>$('#restoreFile').click());else $('#restoreFile').click();}if(el.id==='prevPage'){state.page=Math.max(0,state.page-1);runSearch();}if(el.id==='nextPage'){state.page++;runSearch();}});
$('#unlockForm').onsubmit=e=>{e.preventDefault();if($('#password').value!=='Yh19990125@'){$('#passwordError').textContent='密码不正确，请重新输入。';$('#password').setAttribute('aria-invalid','true');return;}state.unlocked=true;state.epoch++;lastAction=Date.now();$('#password').removeAttribute('aria-invalid');$('#password').value='';$('#lockDialog').close();const after=pending;pending=null;render();if(after)after();};
$('.dialog-close').onclick=()=>{$('#lockDialog').close();pending=null;};$('#lockBtn').onclick=$('#topLock').onclick=()=>state.unlocked?lock():requestUnlock();$('#closeReader').onclick=closeReader;$('#reader').addEventListener('close',()=>{$('#readerBody').replaceChildren();state.current=null;if(printFrame){printFrame.remove();printFrame=null;}});$('#copyBtn').onclick=copyCurrent;$('#printBtn').onclick=printCurrent;$('#templateSelect').onchange=renderRecord;$('#settingsBtn').onclick=()=>navigate('settings');$('#menuBtn').onclick=()=>{const open=$('.sidebar').classList.toggle('open');$('#menuBtn').setAttribute('aria-expanded',String(open));};
$('#searchForm').onsubmit=e=>{e.preventDefault();state.query=$('#searchInput').value.trim();state.page=0;if(['home','settings'].includes(state.module))navigate(state.unlocked?'all':'emergency');else runSearch();};$('#searchInput').addEventListener('input',()=>{lastAction=Date.now();clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(state.scope!=='full'&&!['home','settings'].includes(state.module)){state.query=$('#searchInput').value.trim();state.page=0;runSearch();}},300);});
document.addEventListener('change',e=>{const id=e.target.id;if(id==='categoryFilter'){state.category=e.target.value;state.page=0;runSearch();}if(id==='settingFilter'){state.setting=e.target.value;state.page=0;runSearch();}if(id==='scopeFilter'){state.scope=e.target.value;state.page=0;runSearch();}if(id==='idleSelect'){state.idle=Number(e.target.value);K.setMeta('idleMinutes',state.idle);}if(id==='restoreFile'&&e.target.files[0])restore(e.target.files[0]);});
document.addEventListener('keydown',()=>lastAction=Date.now());setInterval(()=>{if(state.unlocked&&state.idle>0&&Date.now()-lastAction>state.idle*60000)lock();},10000);
window.addEventListener('online',network);window.addEventListener('offline',network);window.addEventListener('hashchange',()=>{const m=location.hash.slice(1)||'home';if(m!==state.module)navigate(m);});
async function start(){network();menu();render();try{await K.open();state.idle=(await K.meta('idleMinutes'))??15;if(window.PORTABLE){state.manifest=(await Portable.ready()).manifest;await refreshReady();state.progressMessage='全部资料随包提供，无需联网或导入，按需读取。';const initial=location.hash.slice(1);if(initial&&initial!=='home')navigate(initial);else render();return;}if('serviceWorker' in navigator&&isSecureContext)await navigator.serviceWorker.register('sw.js');const response=await fetch('data/manifest.json');if(!response.ok)throw Error('无法读取资料清单');state.manifest=await response.json();await refreshReady();state.progressMessage=state.ready.emergency?'急救资料已在本机，其他模块可继续准备。':'正在准备免密码急救资料';const initial=location.hash.slice(1);if(initial&&initial!=='home')navigate(initial);else render();if(!state.ready.emergency)await prepare(false);}catch(e){state.progressMessage='无法准备本机资料：'+chineseError(e,'请检查网络、浏览器存储权限和可用空间后重试。');render();toast(state.progressMessage);}}
start();

function portableSettings(){$('#view').innerHTML='<div class="welcome"><div><p class="eyebrow">无需安装 · 完全本地</p><h1>便携资料与设置</h1></div></div><div class="settings-layout"><div class="panel"><h2>完整资料随包提供</h2><p>本版直接从当前文件夹按需读取资料，不需要启动服务，也不需要先把全部正文导入浏览器。首页只加载轻量目录，正文最多暂存两个分块。</p><p>急救始终免密码，其余四个模块使用原有本地界面锁。</p><button class="outline" data-action="prepare">逐块校验本地资料文件</button><progress max="100" value="'+state.progress+'" aria-label="文件核对进度"></progress><p class="progress-msg">'+esc(state.progressMessage)+'</p></div><div class="panel"><h2>复制、备份与恢复</h2><p>完整文件夹就是资料备份。复制整个文件夹到U盘或其他电脑，双击“打开临床工作站.html”即可使用；不要只复制单个网页。</p><p>本版不会修改资料文件。恢复资料请重新解压完整运行包。闲置时间设置尽量保存在当前浏览器；即使浏览器不允许保存设置，也可正常查阅。每次打开默认锁定。</p></div><div class="panel"><h2>自动锁定</h2><label for="idleSelect">闲置多久后锁定受保护资料</label><select id="idleSelect"><option value="0">不自动锁定</option><option value="5">5 分钟</option><option value="15">15 分钟</option><option value="30">30 分钟</option></select><p>仅锁定本地界面，资料未加密；锁定不影响急救。</p></div><div class="panel"><h2>使用范围</h2><p>需要电脑已有支持本应用的浏览器，目标为Chrome或Edge第109版及以上。浏览器、系统、打印服务、医院安全策略可能影响使用，不能保证所有电脑或所有浏览器都能运行。</p><p>绿色来自提供的图片，色值为 #45AF2A。源文书内部原有样式保持不变。</p></div></div>';$('#idleSelect').value=String(state.idle);}
